/*
 * A037015  Numbers n with property that, reading binary expansion of n from
 *          right to left, run lengths strictly increase.
 * https://oeis.org/A037015
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, base, nice
 * Formula:   a(n) is generated by enumerating all partitions of the bit
 *            length into distinct parts and constructing the binary number
 *            with runs strictly increasing from the least significant bit
 * Range:     u8 n <= 25, u16 n <= 169, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* Comparator for qsort (works for arbitrary-precision seq_t as well) */
static int cmp_seq_t(const void *a, const void *b) {
    const seq_t *x = (const seq_t *)a;
    const seq_t *y = (const seq_t *)b;
    if (*x < *y) return -1;
    if (*x > *y) return 1;
    return 0;
}

/* Dynamic cache for the sequence values */
static struct {
    seq_t *data;    /* array of values */
    size_t size;    /* number of values stored */
    size_t cap;     /* allocated capacity */
    int curBits;    /* largest bit length that has been generated so far */
} cache = { NULL, 0, 0, 0 };

/* Push a value into the dynamic array, growing it if needed */
static void push_seq(seq_t **arr, size_t *size, size_t *cap, seq_t val) {
    if (*size == *cap) {
        size_t newCap = (*cap == 0) ? 4 : (*cap << 1);
        seq_t *tmp = (seq_t *)realloc(*arr, newCap * sizeof(seq_t));
        if (!tmp) exit(1); /* allocation failure */
        *arr = tmp;
        *cap = newCap;
    }
    (*arr)[*size] = val;
    ++*size;
}

/* Recursive generation of partitions and construction of numbers.
   'rem'   : bits remaining to allocate
   'last'  : smallest allowed part (ensures distinct, increasing parts)
   'depth' : number of parts selected so far
   'parts' : array of selected parts (run lengths) */
static void rec_generate(int rem, int last, int depth,
                         int *parts, seq_t **arr, size_t *size, size_t *cap) {
    if (rem == 0) {
        int m = depth;                    /* number of runs */
        int startBit = (m & 1) ? 1 : 0;    /* ensures most‑significant run is 1 */
        seq_t val = 0;
        for (int idx = m - 1; idx >= 0; --idx) {
            int L   = parts[idx];
            int bit = startBit ^ (idx & 1);
            for (int i = 0; i < L; ++i) {
                val <<= 1;
                if (bit) val |= 1;
            }
        }
        push_seq(arr, size, cap, val);
        return;
    }
    for (int p = last + 1; p <= rem; ++p) {
        parts[depth] = p;
        rec_generate(rem - p, p, depth + 1, parts, arr, size, cap);
    }
}

/* Generate all numbers of a given bit length 'bits' and append them to the cache */
static void generate_numbers_of_bits(int bits, seq_t **arr, size_t *size, size_t *cap) {
    int parts[128];                    /* enough for bits up to 128 */
    rec_generate(bits, 0, 0, parts, arr, size, cap);
}

/* Public function required by the framework */
seq_t a(idx_t n) {
    if (n == 0) return 0;              /* safety: undefined index, return 0 */

    /* Initialise cache on first call */
    if (cache.size == 0) {
        push_seq(&cache.data, &cache.size, &cache.cap, 0); /* a(1) = 0 */
        cache.curBits = 0;                  /* no bits generated yet */
    }

    /* Grow the cache until it contains at least n elements */
    while (cache.size < (size_t)n) {
        ++cache.curBits;
        generate_numbers_of_bits(cache.curBits,
                                 &cache.data, &cache.size, &cache.cap);
    }

    /* Sort the cached values after any new numbers are added */
    qsort(cache.data, cache.size, sizeof(seq_t), cmp_seq_t);

    return cache.data[n - 1];
}
